<?php

declare(strict_types=1);require_once __DIR__.'/../includes/layout.php';require_once __DIR__.'/../includes/google_drive.php';require_once __DIR__.'/../includes/face_service.php';require_login();set_time_limit(0);$eventId=filter_input(INPUT_GET,'event',FILTER_VALIDATE_INT)?:filter_input(INPUT_POST,'event_id',FILTER_VALIDATE_INT);$s=db()->prepare('SELECT * FROM events WHERE id=? LIMIT 1');$s->execute([$eventId]);$event=$s->fetch();if(!$event){http_response_code(404);exit('ไม่พบกิจกรรม');}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$files=drive_list_images($event['drive_folder_id']);$dir=STORAGE_PATH.'/photos/'.$event['id'];if(!is_dir($dir)&&!mkdir($dir,0775,true)&&!is_dir($dir))throw new RuntimeException('สร้างโฟลเดอร์ไม่สำเร็จ');$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];$synced=0;$indexed=0;$failed=[];foreach($files as $file){$mime=(string)($file['mimeType']??'');if(!isset($ext[$mime]))continue;$relative='storage/photos/'.$event['id'].'/'.preg_replace('/[^a-zA-Z0-9_-]/','',(string)$file['id']).'.'.$ext[$mime];$absolute=dirname(__DIR__).'/'.$relative;$modified=date('Y-m-d H:i:s',strtotime((string)($file['modifiedTime']??'now')));$q=db()->prepare('SELECT id,drive_modified_at FROM photos WHERE event_id=? AND drive_file_id=? LIMIT 1');$q->execute([$event['id'],$file['id']]);$old=$q->fetch();$needs=!$old||!is_file($absolute)||(string)$old['drive_modified_at']!==$modified;if($needs)drive_download((string)$file['id'],$absolute);$up=db()->prepare('INSERT INTO photos(event_id,drive_file_id,file_name,mime_type,local_path,file_size,drive_modified_at,is_visible,face_indexed,created_at,updated_at) VALUES(?,?,?,?,?,?,?,1,0,NOW(),NOW()) ON DUPLICATE KEY UPDATE file_name=VALUES(file_name),mime_type=VALUES(mime_type),local_path=VALUES(local_path),file_size=VALUES(file_size),drive_modified_at=VALUES(drive_modified_at),updated_at=NOW()');$up->execute([$event['id'],$file['id'],$file['name'],$mime,$relative,(int)($file['size']??filesize($absolute)),$modified]);$photoId=$old?(int)$old['id']:(int)db()->lastInsertId();if(!$photoId){$q=db()->prepare('SELECT id FROM photos WHERE event_id=? AND drive_file_id=?');$q->execute([$event['id'],$file['id']]);$photoId=(int)$q->fetchColumn();}$synced++;if($needs||!$old){try{$r=face_index_photo((int)$event['id'],$photoId,$absolute);$faces=(int)($r['faces']??0);db()->prepare('UPDATE photos SET face_indexed=? WHERE id=?')->execute([$faces>0?1:0,$photoId]);if($faces>0)$indexed++;else$failed[]='ไม่พบใบหน้า: '.$file['name'];}catch(Throwable $e){$failed[]='ทำดัชนีไม่สำเร็จ: '.$file['name'].' — '.$e->getMessage();}}}$_SESSION['sync_failures']=$failed;audit('sync_event',(string)$event['id']);flash('success',"ซิงก์ {$synced} รูป และทำดัชนี {$indexed} รูป");redirect('admin/sync.php?event='.$event['id']);}catch(Throwable $e){$error=$e->getMessage();}}$failures=$_SESSION['sync_failures']??[];unset($_SESSION['sync_failures']);page_header('ซิงก์รูป',true);require __DIR__.'/_nav.php';?><h1>ซิงก์รูป: <?=e($event['title'])?></h1><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif?><?php foreach($failures as $f):?><div class="notice error"><?=e($f)?></div><?php endforeach?><div class="form-card"><p><strong>Folder ID:</strong> <?=e($event['drive_folder_id'])?></p><p>ระบบดาวน์โหลดเฉพาะไฟล์ใหม่หรือไฟล์ที่แก้ไข แล้วตรวจจับทุกใบหน้าในแต่ละรูป</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="event_id" value="<?=(int)$event['id']?>"><button class="btn">เริ่มซิงก์และทำดัชนี</button></form></div><?php page_footer();?>
